`timescale 1ns/1ps
// Test-only structural verifier for a full-year word generated by the
// independent Python exact-unrank oracle. This bench DOES NOT
// implement or claim a native SV whole-year lexical unranking.
module tb_weave_reference_structure;
    localparam integer DAYS=4244, MONTHS=45;
    logic [7:0] word [0:DAYS-1];
    integer month_length[1:MONTHS],count[1:MONTHS];
    integer first_seen[1:MONTHS],last_seen[1:MONTHS];
    integer i,j,ordinal,next_fresh,foundation_count;
    initial begin
        month_length[1]=115;
        month_length[2]=108;
        month_length[3]=119;
        month_length[4]=109;
        month_length[5]=106;
        month_length[6]=81;
        month_length[7]=115;
        month_length[8]=114;
        month_length[9]=117;
        month_length[10]=120;
        month_length[11]=98;
        month_length[12]=52;
        month_length[13]=81;
        month_length[14]=97;
        month_length[15]=121;
        month_length[16]=97;
        month_length[17]=115;
        month_length[18]=96;
        month_length[19]=107;
        month_length[20]=61;
        month_length[21]=106;
        month_length[22]=115;
        month_length[23]=119;
        month_length[24]=39;
        month_length[25]=84;
        month_length[26]=103;
        month_length[27]=115;
        month_length[28]=107;
        month_length[29]=55;
        month_length[30]=119;
        month_length[31]=97;
        month_length[32]=50;
        month_length[33]=122;
        month_length[34]=110;
        month_length[35]=81;
        month_length[36]=54;
        month_length[37]=101;
        month_length[38]=83;
        month_length[39]=88;
        month_length[40]=40;
        month_length[41]=25;
        month_length[42]=77;
        month_length[43]=98;
        month_length[44]=122;
        month_length[45]=105;
        for(j=1;j<=MONTHS;j=j+1) begin
            count[j]=0; first_seen[j]=0;last_seen[j]=0;
        end
        $readmemh("build/foundation_weave_all4244.hex",word);
        next_fresh=1;
        foundation_count=0;
        for(i=0;i<DAYS;i=i+1) begin
            ordinal=int'(word[i]);
            if(ordinal<1 || ordinal>MONTHS)
                $fatal(1,"FULL_YEAR_SV_INVALID_MONTH_ORDINAL at=%0d",i);
            count[ordinal]=count[ordinal]+1;
            last_seen[ordinal]=i+1;
            if(count[ordinal]==1) begin
                if(ordinal!=next_fresh)
                    $fatal(1,"FULL_YEAR_SV_FIRST_OCCURRENCE_ORDER");
                first_seen[ordinal]=i+1;
                next_fresh=next_fresh+1;
            end
            if(i==2031) begin
                foundation_count=count[ordinal];
                if(ordinal!=8 || foundation_count!=56)
                    $fatal(1,"FULL_YEAR_SV_FOUNDATION_POSITION");
            end
        end
        if(next_fresh!=MONTHS+1)
            $fatal(1,"FULL_YEAR_SV_MONTH_FIRST_OCCURRENCES");
        for(j=1;j<=MONTHS;j=j+1) begin
            if(count[j]!=month_length[j])
                $fatal(1,"FULL_YEAR_SV_MONTH_LENGTH at=%0d",j);
            if(j>1 && (first_seen[j]<=first_seen[j-1] ||
                       last_seen[j]<=last_seen[j-1]))
                $fatal(1,"FULL_YEAR_SV_FIRST_LAST_ORDER");
        end
        if(word[0]!==8'd1 || word[DAYS-1]!==8'd45)
            $fatal(1,"FULL_YEAR_SV_FIRST_LAST_SYMBOL");
        if(word[0]!=1 || word[1]!=2 || word[2]!=3 ||
           word[3]!=4 || word[4]!=5 || word[5]!=6 ||
           word[6]!=7 || word[7]!=4 || word[8]!=8 ||
           word[9]!=9 || word[10]!=10)
            $fatal(1,"FULL_YEAR_SV_PREFIX11");
        $display("STAGE1_FOUNDATION_FULL_YEAR_STRUCTURAL_SV_PASS days=4244 months=45 firstlast=ordered ordinal2032=8 occurrence=56");
        $finish;
    end
endmodule
